<?php
require_once __DIR__ . '/config.php';
require_login();
$role = $_SESSION['role'];
$recent = [];
if ($role === 'admin' || $role === 'hod') {
    $recent = $pdo->query("SELECT a.scanned_at,a.status,a.distance_meters,u.full_name,u.login_id,s.subject FROM faculty_attendance a JOIN users u ON u.id=a.faculty_user_id JOIN qr_sessions s ON s.id=a.qr_session_id ORDER BY a.scanned_at DESC LIMIT 20")->fetchAll();
} else {
    $stmt = $pdo->prepare("SELECT a.scanned_at,a.status,a.distance_meters,s.subject FROM faculty_attendance a JOIN qr_sessions s ON s.id=a.qr_session_id WHERE a.faculty_user_id=? ORDER BY a.scanned_at DESC LIMIT 20");
    $stmt->execute([$_SESSION['user_id']]); $recent = $stmt->fetchAll();
}
$sessions = $role === 'admin' ? $pdo->query("SELECT * FROM qr_sessions ORDER BY created_at DESC LIMIT 10")->fetchAll() : [];
$campus = $pdo->query("SELECT * FROM campus_locations ORDER BY id LIMIT 1")->fetch();
?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>LEAPHIGHER Dashboard</title><link rel="stylesheet" href="assets/style.css"></head>
<body><header class="topbar"><a class="logo" href="dashboard.php">LEAPHIGHER</a><div><?=h($_SESSION['full_name'])?> · <?=h(strtoupper($role))?> <a class="logout" href="logout.php">Logout</a></div></header>
<div class="layout"><aside class="sidebar"><a class="active" href="dashboard.php">Dashboard</a><?php if ($role === 'faculty'): ?><a href="scan.php">Scan QR Attendance</a><?php endif; ?></aside>
<main class="content"><p class="eyebrow">ATTENDANCE MANAGEMENT</p><h1>Welcome, <?=h($_SESSION['full_name'])?></h1><p class="muted">Your LEAPHIGHER attendance workspace.</p>
<div class="stats"><div class="stat"><span>Role</span><strong><?=h(ucfirst($role))?></strong></div><div class="stat"><span>Department</span><strong><?=h($_SESSION['department'] ?: '—')?></strong></div><div class="stat"><span>Today's date</span><strong><?=date('d M Y')?></strong></div></div>
<?php if ($role === 'admin'): ?>
<section class="panel"><h2>Create QR attendance session</h2><form method="post" action="create_session.php" class="form-grid"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><div><label>Subject / Class</label><input name="subject" required placeholder="Software Engineering"></div><div><label>Start time</label><input type="datetime-local" name="starts_at" required></div><div><label>End time</label><input type="datetime-local" name="ends_at" required></div><div class="form-action"><button class="btn" type="submit">Generate QR Session</button></div></form></section>
<section class="panel"><h2>Campus GPS settings</h2><p class="muted">Enter the actual LEAPHIGHER campus coordinates. The default 0,0 is not a valid campus setup.</p><form method="post" action="save_campus.php" class="form-grid"><input type="hidden" name="csrf_token" value="<?=h(csrf_token())?>"><div><label>Campus name</label><input name="campus_name" required value="<?=h($campus['campus_name'] ?? 'LEAPHIGHER Campus')?>"></div><div><label>Latitude</label><input type="number" step="0.0000001" name="latitude" required value="<?=h((string)($campus['latitude'] ?? '0'))?>"></div><div><label>Longitude</label><input type="number" step="0.0000001" name="longitude" required value="<?=h((string)($campus['longitude'] ?? '0'))?>"></div><div><label>Allowed radius (metres)</label><input type="number" min="20" max="2000" name="radius_meters" required value="<?=h((string)($campus['radius_meters'] ?? '150'))?>"></div><div class="form-action"><button class="btn secondary" type="submit">Save campus settings</button></div></form></section>
<section class="panel"><h2>Recent QR sessions</h2><div class="table-wrap"><table><tr><th>Subject</th><th>Starts</th><th>Ends</th><th>QR</th></tr><?php foreach ($sessions as $s): ?><tr><td><?=h($s['subject'])?></td><td><?=h($s['starts_at'])?></td><td><?=h($s['ends_at'])?></td><td><button class="link-btn" onclick='showQr(<?=json_encode($s['token'])?>,<?=json_encode($s['subject'])?>)'>Show QR</button></td></tr><?php endforeach; ?></table></div><div id="qr-area" class="qr-area"></div></section>
<?php elseif ($role === 'faculty'): ?>
<section class="panel"><h2>Faculty attendance</h2><p>Scan the QR code generated by your administrator during the scheduled session.</p><a class="btn" href="scan.php">Open QR Scanner</a></section>
<?php else: ?>
<section class="panel"><h2>HOD access</h2><p>Review the attendance records available to your department. Department filtering can be added to your deployment.</p></section>
<?php endif; ?>
<section class="panel"><h2><?=($role==='faculty'?'My attendance history':'Recent faculty attendance')?></h2><div class="table-wrap"><table><tr><?php if ($role !== 'faculty'): ?><th>Faculty</th><th>Faculty ID</th><?php endif; ?><th>Subject</th><th>Server time</th><th>Distance</th><th>Status</th></tr><?php foreach ($recent as $r): ?><tr><?php if ($role !== 'faculty'): ?><td><?=h($r['full_name'])?></td><td><?=h($r['login_id'])?></td><?php endif; ?><td><?=h($r['subject'])?></td><td><?=h($r['scanned_at'])?></td><td><?=h((string)$r['distance_meters'])?> m</td><td><span class="pill"><?=h($r['status'])?></span></td></tr><?php endforeach; ?><?php if (!$recent): ?><tr><td colspan="6">No attendance records yet.</td></tr><?php endif; ?></table></div></section>
</main></div>
<script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script><script>
function showQr(token, subject){const area=document.getElementById('qr-area');area.innerHTML='<h3>'+subject+'</h3><div id="qrcode"></div><p class="small muted">Faculty scan this QR during the scheduled session.</p>';new QRCode(document.getElementById('qrcode'),{text:token,width:220,height:220});area.scrollIntoView({behavior:'smooth'});}
</script></body></html>
